MANIPULATION_TICKS = sum(segment.duration for segment in HAND_MOTION_SEGMENTS)
RAMP_TICKS = 80
CONVEY_TICKS = 180
BRAKE_TICKS = 160
HOLD_TICKS = 240
_BLUE_PUSH_SEGMENT_INDEX = next(
    index
    for index, segment in enumerate(HAND_MOTION_SEGMENTS)
    if segment.phase == "blue_push"
)
BELT_START_TICKS = sum(
    segment.duration
    for segment in HAND_MOTION_SEGMENTS[: _BLUE_PUSH_SEGMENT_INDEX + 1]
)
CYCLE_TICKS = max(
    MANIPULATION_TICKS,
    BELT_START_TICKS + RAMP_TICKS + CONVEY_TICKS + BRAKE_TICKS,
) + HOLD_TICKS
# Damping helps a freely carried parcel settle. The blue mailer now crosses the
# balance point geometrically while suspended, so it keeps damping throughout
# the lift and transfer. The original table-supported yellow turn still needs
# its undamped angular momentum.
SOFT_DAMPING_DISABLED_PHASES = frozenset(
    ("yellow_flip_rotate",)
)
QUALITY_ENVIRONMENT_VARIABLE = "GOBOT_CONVEYOR_QUALITY"


@dataclass(frozen=True)
class ConveyorQualityProfile:
    name: str
    contact_refresh_interval: int
    newton_max_iterations: int
    line_search_max_iterations: int


QUALITY_PROFILES = {
    "interactive": ConveyorQualityProfile(
        name="interactive",
        contact_refresh_interval=4,
        newton_max_iterations=16,
        line_search_max_iterations=8,
    ),
    "accurate": ConveyorQualityProfile(
        name="accurate",
        contact_refresh_interval=1,
        # Dense fingertip/shell contact occasionally needs more than the
        # interactive cap; Newton still exits early on ordinary frames.
        newton_max_iterations=48,
        line_search_max_iterations=8,
    ),
}


def quality_profile(name: str | None = None) -> ConveyorQualityProfile:
    selected = (
        name
        if name is not None
        else os.environ.get(QUALITY_ENVIRONMENT_VARIABLE, "interactive")
    )
    selected = str(selected).strip().lower()
    try:
        return QUALITY_PROFILES[selected]
    except KeyError as error:
        choices = ", ".join(repr(value) for value in QUALITY_PROFILES)
        raise ValueError(
            f"{QUALITY_ENVIRONMENT_VARIABLE} must be one of {choices}"
        ) from error


def smoothstep(value: float) -> float:
    value = max(0.0, min(1.0, float(value)))
    return value * value * (3.0 - 2.0 * value)


def belt_speed_at_tick(tick: int) -> float:
    tick = max(0, int(tick))
    if tick < BELT_START_TICKS:
        return 0.0
    tick -= BELT_START_TICKS
    if tick < RAMP_TICKS:
        return BELT_SPEED * smoothstep(float(tick + 1) / RAMP_TICKS)
    tick -= RAMP_TICKS
    if tick < CONVEY_TICKS:
        return BELT_SPEED
    tick -= CONVEY_TICKS
    if tick < BRAKE_TICKS:
        return BELT_SPEED * (
            1.0 - smoothstep(float(tick + 1) / BRAKE_TICKS)
        )
    return 0.0


def _lerp_targets(
    start: tuple[tuple[float, ...], ...],
    end: tuple[tuple[float, ...], ...],
    fraction: float,
) -> tuple[tuple[float, ...], ...]:
    return tuple(
        tuple(
            start_value + (end_value - start_value) * fraction
            for start_value, end_value in zip(
                start_hand, end_hand, strict=True
            )
        )
        for start_hand, end_hand in zip(start, end, strict=True)
    )


def _transition(
    tick: int,
    duration: int,
    start: tuple[tuple[float, ...], ...],
    end: tuple[tuple[float, ...], ...],
) -> tuple[tuple[float, ...], ...]:
    fraction = smoothstep(float(tick + 1) / duration)
    return _lerp_targets(start, end, fraction)


def _motion_segment_at_tick(
    tick: int,
) -> tuple[HandMotionSegment | None, int]:
    local_tick = max(0, int(tick))
    for segment in HAND_MOTION_SEGMENTS:
        if local_tick < segment.duration:
            return segment, local_tick
        local_tick -= segment.duration
    return None, 0


def hand_stage_targets_at_tick(
    tick: int,
) -> tuple[tuple[float, ...], ...]:
    segment, local_tick = _motion_segment_at_tick(tick)
    if segment is None:
        return HAND_MOTION_SEGMENTS[-1].end
    if segment.phase == "blue_flip_rotate":
        fraction = smoothstep(float(local_tick + 1) / segment.duration)
        return _pinched_edge_turnover_targets(
            HAND_STAGE_BLUE_FLIP_STABILIZE_TARGETS,
            fraction=fraction,
            forward_travel=BLUE_FLIP_EDGE_FORWARD_TRAVEL,
            end_lift=BLUE_FLIP_EDGE_END_LIFT,
            arc_height=BLUE_FLIP_EDGE_ARC_HEIGHT,
        )
    if segment.phase == "blue_flip_turnover":
        fraction = smoothstep(float(local_tick + 1) / segment.duration)
        return _table_pivot_turnover_targets(
            HAND_STAGE_BLUE_FLIP_PLACE_TARGETS,
            fraction=fraction,
            forward_travel=BLUE_FLIP_TURNOVER_FORWARD_TRAVEL,
            drop=BLUE_FLIP_TURNOVER_DROP,
        )
    if segment.phase == "yellow_flip_rotate":
        fraction = smoothstep(float(local_tick + 1) / segment.duration)
        return _pinched_edge_turnover_targets(
            HAND_STAGE_YELLOW_FLIP_STABILIZE_TARGETS,
            fraction=fraction,
            forward_travel=YELLOW_FLIP_EDGE_FORWARD_TRAVEL,
            end_lift=YELLOW_FLIP_EDGE_END_LIFT,
            arc_height=YELLOW_FLIP_EDGE_ARC_HEIGHT,
        )
    return _transition(
        local_tick,
        segment.duration,
        segment.start,
        segment.end,
    )


def _finger_close_pair(
    value: float | tuple[float, float],
) -> tuple[float, float]:
    if isinstance(value, tuple):
        if len(value) != 2:
            raise ValueError("finger close target must contain two hands")
        return (float(value[0]), float(value[1]))
    scalar = float(value)
    return (scalar, scalar)


def finger_close_fractions_at_tick(tick: int) -> tuple[float, float]:
    segment, local_tick = _motion_segment_at_tick(tick)
    if segment is None:
        return (0.0, 0.0)
    fraction = smoothstep(float(local_tick + 1) / segment.duration)
    close_start = _finger_close_pair(segment.close_start)
    close_end = _finger_close_pair(segment.close_end)
    return tuple(
        start + (end - start) * fraction
        for start, end in zip(close_start, close_end, strict=True)
    )


def finger_close_fraction_at_tick(tick: int) -> float:
    """Return the strongest hand closure for compact UI diagnostics."""
    return max(finger_close_fractions_at_tick(tick))


def hand_finger_targets_at_tick(
    tick: int,
) -> tuple[tuple[float, ...], ...]:
    segment, _ = _motion_segment_at_tick(tick)
    close_fractions = finger_close_fractions_at_tick(tick)
    blue_air_pinch = segment is not None and segment.phase.startswith(
        "blue_flip_"
    )
    soft_pinch = segment is not None and segment.phase.startswith(
        "yellow_flip_"
    )
    if blue_air_pinch:
        full_targets = LEAP_BLUE_AIR_PINCH_TARGETS_BY_SIDE
    elif soft_pinch:
        full_targets = LEAP_SOFT_PINCH_TARGETS_BY_SIDE
    else:
        full_targets = (LEAP_FINGER_CLOSE_TARGETS,) * 2
    return tuple(
        tuple(value * close_fraction for value in targets)
        for targets, close_fraction in zip(
            full_targets, close_fractions, strict=True
        )
    )


def hand_controls_at_tick(tick: int) -> tuple[tuple[float, ...], ...]:
    stage_targets = hand_stage_targets_at_tick(tick)
    return tuple(
        stage + finger_targets
        for stage, finger_targets in zip(
            stage_targets,
            hand_finger_targets_at_tick(tick),
            strict=True,
        )
    )


def cycle_phase(tick: int) -> str:
    segment, _ = _motion_segment_at_tick(tick)
    return segment.phase if segment is not None else "settle"


def soft_damping_scale_at_tick(tick: int) -> float:
    """Return the deformable velocity-damping multiplier for one step."""
    return 0.0 if cycle_phase(tick) in SOFT_DAMPING_DISABLED_PHASES else 1.0
